CFDLean.Assembly.global_balance.type:
∀ {N : Type u_1} {E : Type u_2} {B : Type u_3} [inst : DecidableEq N] [inst_1 : Fintype E] [inst_2 : Fintype B] {d : ℕ}
  [inst_3 : Fintype N] (m : CFDLean.Assembly.Interfaces N E B) (f : E → CFDLean.Vector d) (g : B → CFDLean.Vector d),
  ∑ i, CFDLean.Assembly.residual m f g i = ∑ b, g b

CFDLean.Num.dissipativePairFlux_freeStre.type:
∀ (ι S κ : Type) [inst : Fintype ι] [DecidableEq ι] [Fintype κ] (d : ℕ) (Fec : S → S → CFDLean.Num.Vec d → κ → ℝ)
  (phys : S → CFDLean.Num.Vec d → κ → ℝ) (n : ι → ι → CFDLean.Num.Vec d) (U : S) (ut0 : κ → ℝ)
  (lam eps2 eps4 : ι → ι → ℝ) (Nstar : ι → Finset ι),
  (∀ (a b : S), IsLinearMap ℝ (Fec a b)) →
    (∀ (y : CFDLean.Num.Vec d), Fec U U y = phys U y) →
      let beta := fun i => -∑ k, n i k;
      let L := fun i => ∑ _k ∈ Nstar i, (ut0 - ut0);
      let F := fun i k => Fec U U (n i k) + lam i k • (eps2 i k • (ut0 - ut0) - eps4 i k • (L i - L k));
      ∀ (i : ι), -∑ k, F i k - phys U (beta i) = 0

CFDLean.PhysicalJacobian.jacobian_action.type:
∀ (γ : ℝ) (U V : CFDLean.Conservative 3) (n : CFDLean.Vector 3),
  let u := fun i => U.momentum i / U.density;
  let q := CFDLean.dot u n;
  let b := CFDLean.dot V.momentum n - q * V.density;
  let dp := (γ - 1) * (V.energy - CFDLean.dot u V.momentum + CFDLean.squareSum u / 2 * V.density);
  let H := (U.energy + CFDLean.Conservative.pressure γ U) / U.density;
  (CFDLean.PhysicalJacobian.jacobian γ (CFDLean.Coordinates.encode U) n) (CFDLean.Coordinates.encode V) =
    CFDLean.Coordinates.encode
      { density := CFDLean.dot V.momentum n, momentum := fun i => q * V.momentum i + u i * b + dp * n i,
        energy := q * (V.energy + dp) + H * b }

CFDLean.PhysicalJacobian.jacobian_action.raw_type:
∀ (γ : Real) (U V : CFDLean.Conservative (OfNat.ofNat 3)) (n : CFDLean.Vector (OfNat.ofNat 3)),
  let u := fun i => HDiv.hDiv (U.momentum i) U.density;
  let q := CFDLean.dot u n;
  let b := HSub.hSub (CFDLean.dot V.momentum n) (HMul.hMul q V.density);
  let dp :=
    HMul.hMul (HSub.hSub γ (OfNat.ofNat 1))
      (HAdd.hAdd (HSub.hSub V.energy (CFDLean.dot u V.momentum))
        (HMul.hMul (HDiv.hDiv (CFDLean.squareSum u) (OfNat.ofNat 2)) V.density));
  let H := HDiv.hDiv (HAdd.hAdd U.energy (CFDLean.Conservative.pressure γ U)) U.density;
  Eq
    (DFunLike.coe (CFDLean.PhysicalJacobian.jacobian γ (CFDLean.Coordinates.encode U) n) (CFDLean.Coordinates.encode V))
    (CFDLean.Coordinates.encode
      { density := CFDLean.dot V.momentum n,
        momentum := fun i =>
          HAdd.hAdd (HAdd.hAdd (HMul.hMul q (V.momentum i)) (HMul.hMul (u i) b)) (HMul.hMul dp (n i)),
        energy := HAdd.hAdd (HMul.hMul q (HAdd.hAdd V.energy dp)) (HMul.hMul H b) })

